-- Migration 894: retry the specific 50-row sub-batch that keeps failing
-- silently -- isolated standalone, in case it was a transient API issue.


SELECT 'f894_retry_count' AS chk, count(*)::int AS n
  FROM public.daily_records WHERE remarks = 'F20_IMPORT_2026-08-24' AND record_date BETWEEN '2025-12-01' AND '2025-12-13';